<template>
  <div>
    <el-form :inline="true" :model="queryForm" size="small">
      <el-form-item>
        <el-select v-model="queryForm.category">
          <el-option :value="1" label="白名单"></el-option>
          <el-option :value="2" label="黑名单"></el-option>
        </el-select>
      </el-form-item>
      <el-form-item>
        <el-button type="primary" @click="query">查询</el-button>
        <el-button @click="reset">重置</el-button>
      </el-form-item>
    </el-form>
    <el-button
      type="primary"
      plain
      icon="el-icon-plus"
      size="mini"
      @click="addData"
      >新增</el-button
    >
    <el-table
      :data="dataList"
      style="width: 100%"
      class="mt-10"
      v-loading="loading"
      size="small"
    >
      <el-table-column type="index" label="序号" align="center" />
      <el-table-column prop="name" label="姓名" align="center" />
      <el-table-column prop="category" label="人员类别" align="center">
        <template slot-scope="scope">
          {{ scope.row.category == 1 ? "白名单" : "黑名单" }}
        </template>
      </el-table-column>
      <el-table-column prop="images_f" label="人脸1" align="center">
        <template slot-scope="scope">
          <el-image
            style="width: 90px; height: 100px"
            v-if="scope.row.images_f"
            :src="`${scope.row.images_f}`"
            :preview-src-list="[`${scope.row.images_f}`]"
            fit="fill"
            referrerpolicy="no-referrer"
          >
          </el-image>
          <span v-else>暂无图片</span>
        </template>
      </el-table-column>
      <el-table-column prop="images_s" label="人脸2" align="center">
        <template slot-scope="scope">
          <el-image
            style="width: 90px; height: 100px"
            v-if="scope.row.images_s"
            :src="`${scope.row.images_s}`"
            :preview-src-list="[`${scope.row.images_s}`]"
            fit="fill"
            referrerpolicy="no-referrer"
          >
          </el-image>
          <span v-else>暂无图片</span>
        </template>
      </el-table-column>
      <el-table-column prop="images_t" label="人脸3" align="center">
        <template slot-scope="scope">
          <el-image
            style="width: 90px; height: 100px"
            v-if="scope.row.images_t"
            :src="`${scope.row.images_t}`"
            :preview-src-list="[`${scope.row.images_t}`]"
            fit="fill"
            referrerpolicy="no-referrer"
          >
          </el-image>
          <span v-else>暂无图片</span>
        </template>
      </el-table-column>
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button
            type="text"
            @click="editData(scope.row)"
            class="el-icon-edit"
          ></el-button>
          <el-button
            type="text"
            @click="delData(scope.row)"
            class="el-icon-delete"
            style="color: red"
          ></el-button>
        </template>
      </el-table-column>
    </el-table>
    <pagination
      class="float-right mb-10"
      v-show="total > 0"
      :total="total"
      :page.sync="queryForm.page"
      :limit.sync="queryForm.size"
      @pagination="getData"
      layout="total, prev, pager, next"
      small
    />
    <el-dialog
      :title="title"
      :visible.sync="addVisible"
      width="50%"
      :close-on-click-modal="false"
      top="10px"
    >
      <el-form
        :model="addForm"
        ref="addForm"
        label-width="120px"
        class="mt-20"
        size="small"
      >
        <el-form-item label="姓名:" prop="name">
          <el-input v-model="addForm.name" style="width: 40%" />
        </el-form-item>
        <el-form-item label="人员类别:" prop="category">
          <el-select v-model="addForm.category">
            <el-option :value="1" label="白名单"></el-option>
            <el-option :value="2" label="黑名单"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="上传人脸:">
          <Upload
            :file="fileList"
            ref="Upload"
            :fileType="fileType"
            :limit="3"
            ListType="picture-card"
            :showFileList="true"
            @getFile="getFile"
          />
        </el-form-item>
        <el-form-item label="备注" prop="remark">
          <el-input
            type="textarea"
            v-model="addForm.remark"
            :autosize="{ minRows: 6, maxRows: 18 }"
            style="width: 80%"
          ></el-input>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="addVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitForm('addForm')"
          >确 定</el-button
        >
      </span>
    </el-dialog>
  </div>
</template>

<script>
import Upload from "@/components/upload.vue";
export default {
  components: {
    Upload,
  },
  data() {
    return {
      dataList: [],
      loading: false,
      fileList: [],
      addForm: {},
      addVisible: false,
      title: "",
      UploadLoading: false,
      fileType: ["image/jpeg", "image/png"],
      audio: null,
      queryForm: {
        page: 1,
        size: 10,
      },
      total: 0,
    };
  },
  created() {
    this.getData();
  },
  methods: {
    reset() {
      this.queryForm = {
        page: 1,
        size: 10,
      };
      this.getData();
    },
    query() {
      this.queryForm = {
        ...this.queryForm,
        page: 1,
      };
      this.getData();
    },
    getData() {
      this.$api
        .get("/ai/getAiFaceList", {
          params: this.queryForm,
        })
        .then((res) => {
          if (res.data.data) {
            this.dataList = res.data.data;
            this.total = res.data.total;
          } else {
            this.total = 0;
            this.dataList = [];
          }
        });
    },
    addData() {
      this.addForm = {};
      this.fileList = [];
      this.title = "新增";
      this.addVisible = true;
    },
    editData(row) {
      this.title = "编辑";
      this.addVisible = true;
      this.addForm = { ...row };
    },
    delData(row) {
      this.$confirm("是否删除该数据?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api.post("/ai/delAiFace", { id: row.id }).then(() => {
            this.$message.success("操作成功");
            this.getData();
          });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    getFile(data) {
      this.addForm.images_f = data[0];
      this.addForm.images_s = data[1];
      this.addForm.images_t = data[2];
    },
    async convertImages(row) {
      const fileList = ["f", "s", "t"]
        .map((key) => row[`images_${key}`])
        .filter(Boolean)
        .map(async (url) => {
          const file = await this.imageUrlToFile(url);
          return file;
        });
      this.fileList = await Promise.all(fileList);
      this.addForm.images_f = this.fileList[0] || null;
      this.addForm.images_s = this.fileList[1] || null;
      this.addForm.images_t = this.fileList[2] || null;
      return;
    },
    imageUrlToFile(imgUrl) {
      return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.src = imgUrl;
        img.onload = () => {
          const canvas = document.createElement("canvas");
          canvas.width = img.width;
          canvas.height = img.height;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0);
          let ext = "jpg";
          canvas.toBlob((blob) => {
            if (!blob) {
              reject(new Error("Canvas转Blob失败"));
              return;
            }
            // 提取文件扩展名
            const match = imgUrl.match(/\.(\w+)(\?.*)?$/);
            if (match) {
              ext = match[1];
            }
            // 创建文件名
            const fileName = this.getFileName(imgUrl);
            const file = new File([blob], fileName, { type: blob.type });
            file.url = imgUrl;
            resolve(file);
          }, this.getImageMimeType(ext));
        };

        img.onerror = (error) => {
          reject(new Error("图片加载失败: " + error.message));
        };
      });
    },
    getFileName(name) {
      if (name.lastIndexOf("/") > -1) {
        return name.slice(name.lastIndexOf("/") + 1);
      } else {
        return "";
      }
    },
    getImageMimeType(ext) {
      const mimeTypes = {
        jpg: "image/jpeg",
        jpeg: "image/jpeg",
        png: "image/png",
        gif: "image/gif",
        webp: "image/webp",
        bmp: "image/bmp",
      };
      return mimeTypes[ext.toLowerCase()] || "image/jpeg";
    },
    submitForm() {
      let formData = new FormData();
      [
        "images_f",
        "images_s",
        "images_t",
        "name",
        "remark",
        "category",
      ].forEach((key) => {
        if (this.addForm[key] != "") {
          formData.append(key, this.addForm[key]);
        }
      });
      const isEditMode = !!this.addForm.id;
      const apiUrl = isEditMode ? "/ai/updateAiFace" : "/ai/addAiFace";
      if (isEditMode) {
        formData.append("id", this.addForm.id);
      }
      this.$api
        .post(apiUrl, formData, {
          headers: {
            "Content-Type": "multipart/form-data",
          },
          timeout: 600000,
        })
        .then(() => {
          this.UploadLoading = false;
          this.addVisible = false;
          this.$message.success("操作成功");
          this.getData();
        });
    },
  },
};
</script>

<style></style>
